plt.scatter([1.4], [-0.4], color="red", marker="x", s=100, label="Target2 (1.4, -0.4)")
plt.scatter([1.4], [0.4], color="red", marker="x", s=100, label="Target3 (1.4, +0.4)")

# ✅ Proper colorbar with larger font
font_size=22
cbar = plt.colorbar()
cbar.set_label("Density", fontsize=font_size)
cbar.ax.tick_params(labelsize=font_size)

# Axis labels and title
plt.xlabel("X Position [m]", fontsize=font_size)
plt.ylabel("Y Position [m]", fontsize=font_size)
plt.title("Heatmap of Landing Positions", fontsize=font_size)

# ✅ Match axis numbers to legend size
plt.xticks(fontsize=font_size)
plt.yticks(fontsize=font_size)

# ✅ Match legend size explicitly
plt.legend(loc="upper left", fontsize=font_size)

plt.grid(True)
plt.gca().add_patch(rectangle1)
plt.gca().add_patch(rectangle2)
plt.gca().add_patch(rectangle3)

plt.show()

